const tickets = $input.all().map(item => item.json);

const totalTickets = tickets.length;

const openTickets = tickets.filter(ticket => ticket.status === "Open" ).length;

const inProgressTickets = tickets.filter(ticket =>
  ticket.status === "In Progress"
).length;

const resolvedTickets = tickets.filter(ticket =>
  ticket.status === "Resolved"
).length;

const delayedTickets = tickets.filter(ticket =>
  ticket.isDelayed === true
).length;

let resolvedRate = 0;

if (totalTickets > 0) {
  resolvedRate = (resolvedTickets / totalTickets) * 100;}

  let delayedRate = 0;
  if (totalTickets > 0) {delayedRate = (delayedRate / totalTickets) * 100;
                       }

const summary = `Support Ticket Report

Total Tickets: ${totalTickets}
Open Tickets: ${openTickets}
In Progress Tickets: ${inProgressTickets}
Resolved Tickets: ${resolvedTickets}
Delayed Tickets: ${delayedTickets}

Resolved Rate: ${resolvedRate.toFixed(2)}%
Delayed Rate: ${delayedRate.toFixed(2)}%`;

return [{
  json: {
    totalTickets,
    openTickets,
    inProgressTickets,
    resolvedTickets,
    delayedTickets,
    resolvedRate: Number(resolvedRate.toFixed(2)),
    delayedRate: Number(delayedRate.toFixed(2)),
    summary: summary
  }
}];
